pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PoCGame c;

    function setUp() public {
        c = new PoCGame(address(this), 0);
    }

    function _run(address player, uint256 amount) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(amount <= address(this).balance);
        try c.AdjustBetAmounts(amount) {} catch { return; }
        try c.OpenToThePublic() {} catch { return; }
        try c.wager{value: amount}() {} catch { return; }
        bool reverted;
        try c.play() { reverted = false; }
        catch { reverted = true; }
        assertTrue(reverted);
    }

    function testFuzz_run(address player, uint256 amount) public {
        vm.assume(player.code.length == 0 && uint160(player) > 0xffff && player != address(this) && player != address(c) && player != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && player != 0x000000000000000000636F6e736F6c652e6c6f67 && player != 0x4e59b44847b379578588920cA78FbF26c0B4956C && player != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(player, amount);
    }

    receive() external payable {}
}
